return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','pot-creation-date'=>'2026-07-05T18:26:13+00:00','po-revision-date'=>'2026-07-05 19:54+0000','last-translator'=>'admin','language-team'=>'Chinese (China)','language'=>'zh_CN','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" 已保存。','"%1$s" created. %2$d template updated.'=>'“%1$s”已创建。%2$d 个模板已更新。' . "\0" . '','"%s" created.'=>'“%s”已创建。','"product" (replaces "article")'=>'“产品”（取代“文章”）','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'将 H2 视为 H1 等价（设置 → SEO → 分析）：当您的主题将文章标题渲染在 H2 而非 H1 时启用。分析器会将第一个 H2 提升为 H1，以避免得分被错误扣除。','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d 字符 — 良好，略高于理想的 %2$d，但在接受的 %3$d 字符范围内。%4$s','%1$d chars — ideal length. %2$s'=>'%1$d 字符 — 长度良好。%2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d 字符 — 可能在搜索引擎结果页中被截断（保持在 %2$d 以下）。%3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d 个字符 — 太短（目标是 %2$d–%3$d）。%4$s','%1$d chars, %2$d words — good title.'=>'%1$d 字符，%2$d 单词 — 好标题。','%1$d internal, %2$d external.'=>'%1$d 内部链接，%2$d 外部链接。','%1$d of %2$d image(s) missing alt text.'=>'%1$d 个（共 %2$d 个）图像缺少替代文本。','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d 条帖子标记了 _lf_lang = %2$s。' . "\0" . '','%1$d translated, %2$d skipped.'=>'已翻译 %1$d 条，共跳过 %2$d 条。','%1$d words — below recommended minimum of %2$d.'=>'%1$d 个单词 — 低于推荐最少数量 %2$d。','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d 个单词 — 内容过于简洁。请考虑扩展至少到 %2$d 个单词。','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d 已翻译 — <a href="#" class="lf-force-translate">强制重新翻译</a>','%d external link(s), no internal links.'=>'%d 个外部链接，没有内部链接。','%d external link(s), no internal links. Add internal links to related content.'=>'%d 个外部链接，未添加内部链接。请添加相关内容的内部链接。','%d H1 tags found — a page should have exactly one H1.'=>'发现 %d 个H1标签 — 一个页面应只有一个H1标签。','%d image(s), all have alt text.'=>'%d 张图片，全部有alt文本。','%d label(s) translated.'=>'已翻译 %d 个标签。','%d language not yet linked'=>'还未关联%d种语言' . "\0" . '','%d link updated.'=>'%d 个链接已更新。' . "\0" . '','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'无法自动删除 %d 个本地化文件（已设置DISALLOW_FILE_MODS）。请通过服务器或WP-CLI手动删除：wp language core uninstall <locale>' . "\0" . '','%d locale file removed.'=>'已删除 %d 个本地化文件。' . "\0" . '','%d locale pack installed.'=>'已安装%d个区域包。' . "\0" . '','%d navigation reference updated.'=>'%d 个导航引用已更新。' . "\0" . '','%d part reference updated.'=>'%d 个模板部分引用已更新。' . "\0" . '','%d post'=>'%d 条帖子' . "\0" . '','%d rule registered'=>'已注册 %d 条规则' . "\0" . '','%d template repaired.'=>'已修复 %d 个模板。' . "\0" . '','%d term(s) translated.'=>'已翻译 %d 个术语。','%d words.'=>'%d 个单词。','%s Archive'=>'%s 存档','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s 已激活并已输出Schema.org JSON-LD。Lingua Forge已禁用其自身的架构输出，以防止冲突的图表。与Open Graph不同——LF在另一个插件的输出基础上添加og:locale——架构不能被干净地补充：重复或重叠的JSON-LD图表会产生验证错误。如果你希望LF处理结构化数据，请在检测到的插件中禁用架构输出。','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s已激活并生成自己的站点地图。该站点地图与LF的不同。两者都应提交到Google搜索控制台：SEO插件的站点地图列出你的内容；LF的站点地图添加多语言备用链接。LF的站点地图会在robots.txt中自动宣布。','(active)'=>'（激活）','(avg %.1f hits/block)'=>'（平均 %.1f 次/块）','(avg %.1f hits/entry)'=>'（平均 %.1f 次/条目）','(classic theme)'=>'（经典主题）','(disabled)'=>'（已禁用）','(FSE / block theme)'=>'（FSE / 块主题）','(no title) #%d'=>'（无标题） #%d','(partial)'=>'（部分）','(server/FPM timeout still applies)'=>'（服务器/FPM 超时仍然适用）','({skipped} had no replaceable links — re-scan to investigate)'=>'（{skipped}没有可替换的链接——重新扫描以调查）','.txt file(s) in the directory'=>'.txt文件在目录中','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 个 H1 ✓ — 未找到 H2 或 H3 子标题。添加 H2 可改进结构。','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 个 H1 ✓ — 无 H2 子标题（此内容类型可接受）。','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 个 H1 ✓ — 没有 H2，但找到 %d 个 H3 子标题（例如手风琴/详细信息标题）。结构可接受。','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 个 H1 ✓ — 内容简短（%d 段落），不需要子标题。','1 H1 ✓, %1$d H2, %2$d H3.'=>'1个H1 ✓，%1$d个H2，%2$d个H3。','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge：</strong>来自“%2$s”主题的%1$d个本地化模板已保存在数据库中，但目前处于非激活状态。如果你重新激活该主题，它们将再次变为激活状态。要将你的翻译迁移到新主题，请通过<strong>设置 → Lingua Forge → 路由器 → FSE 脚手架</strong>重新生成它们。','<strong>{n}</strong> auto-fixable link(s)'=>'<强>{n}</强>个可自动修复的链接','<strong>{n}</strong> link(s) needing manual review'=>'<强>{n}</强>个需要手动检查的链接','<strong>{n}</strong> stale path(s)'=>'<强>{n}</强>个过时路径','<strong>{n}</strong> template issue(s)'=>'<强>{n}</强>个模板问题','_lf_lang Coverage'=>'_lf_lang 覆盖范围','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'站点根目录存在一个实体robots.txt文件。WordPress的虚拟robots.txt——以及LF的站点地图：过滤器——被绕过。LF的站点地图未向搜索引擎宣布。','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'只接受已编译的 .mo 文件。文件名必须遵循 {textdomain}-{locale}.mo 的模式。上传同名文件将覆盖现有文件。','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'访问被禁止 — 您的账户可能已被暂停或密钥缺少必要权限。','Action'=>'操作','active'=>'激活','Active Languages'=>'活动语言','Active languages'=>'活跃语言','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'活动语言：添加您想支持的每种语言。每种语言都将获得一个 URL 前缀或子域名，以及在页面 &lt;head&gt; 中的 hreflang 标签。','Active Plugins'=>'激活的插件','Active preset'=>'活跃预设','Active Provider'=>'当前提供者','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'活动提供者、配置的密钥、模型层级选择、预设和每日配额。','Active theme'=>'活跃主题','Active: %s.'=>'活跃：%s。','Add entry'=>'添加条目','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'添加指令以改进草稿——例如使其更短，添加结论部分，使用更正式的语体，包含常见问题块……','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'添加改进草稿的指示 — 例如使其更短，添加结论部分，使用更正式的语体…','Add key →'=>'添加键 →','Add new entry'=>'添加新条目','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'每行添加一个术语。源术语和目标渲染都必须提供。语言对决定了约束适用的翻译任务。','Add Sitemap directive to robots.txt'=>'在robots.txt中添加站点地图指令','Add the following line to your robots.txt manually:'=>'请手动在你的robots.txt中添加以下行：','Add WooCommerce product tags to Open Graph output'=>'将WooCommerce产品标签添加到Open Graph输出中','Adds a link to the home page so visitors can browse in their language.'=>'添加一个指向主页的链接，方便访客用他们的语言浏览。','Administrators only (manage_options)'=>'仅管理员（管理选项）','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'更改主要语言后，刷新永久链接（下节）以更新URL路由。','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'更改 URL 结构设置（路径前缀 ↔ 子域名）后，务必访问 设置 → 固定链接 并点击 保存更改 以刷新重写规则。','AI analysis failed. Please try again.'=>'AI分析失败。请重试。','AI Behaviour Preset'=>'AI行为预设','AI cache cleared. %d entry was removed.'=>'AI 缓存已清除。%d 条目已移除。' . "\0" . '','AI Configuration'=>'AI 配置','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI 功能是可选的。语言路由、hreflang、语言切换器和翻译组系统在没有配置提供商的情况下也能正常工作。','AI Limits & Security'=>'AI 限制与安全','AI Provider'=>'AI 提供商','AI provider returned an empty response.'=>'AI提供商返回空响应。','AI Provider Tab'=>'AI 提供者标签页','AI Recommendations'=>'AI建议','AI returned an unexpected response format. Please try again.'=>'AI返回了意外的响应格式。请重试。','AI translation and batch analysis may time out. Recommend 120s or more.'=>'AI 翻译和批量分析可能会超时。建议120秒或更长时间。','AI Usage'=>'AI使用情况','AI Usage & Cache'=>'AI使用与缓存','AI Usage & Cache Tab'=>'AI 使用与缓存标签页','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'目标字符数为120–160个。留空以使用摘录备用。','All labels already translated.'=>'所有标签已全部翻译完毕。','All published posts have a _lf_lang value. No gaps detected.'=>'所有已发布的帖子都具有 _lf_lang 值。未检测到空缺。','All template metadata is already up to date.'=>'所有模板元数据已是最新。','All time'=>'全部时间','All types'=>'所有类型','Allow editors to lock individual blocks'=>'允许编辑者锁定单个块','Allow Gutenberg template-editing mode on post screens'=>'允许在文章屏幕上使用 Gutenberg 模板编辑模式','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'卸载插件时也删除语言分配、翻译关系、元描述、词汇表和翻译记忆','Also generate meta description'=>'也生成元描述','Alternative (server-side):'=>'备用（服务器端）：','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'始终只发出og:locale和og:locale:alternate。当另一个插件或主题处理完整的OG集时使用。','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'始终发出完整的OG + Twitter卡片集，无论其他插件如何。仅在没有其他插件输出OG标签时使用。','An unknown error occurred.'=>'发生未知错误。','Analyse'=>'分析','Analyse all languages'=>'分析所有语言','Analyse…'=>'分析…','Analysis'=>'分析','Analysis request failed. Please try again.'=>'分析请求失败。请重试。','Analyzing…'=>'分析中…','and'=>'和','and set it to one of your actual content languages (e.g. %s).'=>'并将其设置为您的实际内容语言之一（例如 %s）。','Anthropic (Claude)'=>'Anthropic（Claude）','Anthropic Console'=>'Anthropic 控制台','any'=>'任意','API calls saved by cache'=>'由缓存保存的 API 调用','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'API 凭据由 WordPress 在 %s 管理。Lingua Forge 不存储任何密钥。','API Key'=>'API密钥','API Keys'=>'API密钥','API Response Cache'=>'API 响应缓存','API Response Cache setting saved.'=>'API 响应缓存设置已保存。','Appends the following line to your existing robots.txt: %s'=>'在你现有的robots.txt中添加以下行：%s','Applied ✓'=>'已应用 ✓','Apply failed — please try again.'=>'应用失败——请重试。','Apply to all language versions'=>'应用到所有语言版本','Apply to Block'=>'应用到块','Apply to Editor'=>'应用到编辑器','Apply to Footnote'=>'应用到脚注','Apply to Meta Description'=>'应用到Meta描述','Apply translation'=>'应用翻译','Applying…'=>'正在应用…','Approximate size'=>'大致大小','Archive'=>'存档','Archive: %s'=>'存档：%s','Article / WebPage'=>'文章 / 网页','Article / WebPage — all singular posts and pages'=>'文章 / 网页——所有单一的帖子和页面','Attribute label displayed in this language. Leave empty to use the default label.'=>'以此语言显示的属性标签。留空以使用默认标签。','Authors and above (edit_published_posts)'=>'作者及以上（编辑已发布的文章）','Auto (recommended)'=>'自动（推荐）','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'自动检测分配：WooCommerce 产品 → 产品配置文件；静态首页 → 着陆页配置文件；其他一切 → 博客配置文件。选择特定配置文件以覆盖所有帖子。','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'为静态首页自动检测；也可手动选择。标题 20 分 · 元描述 30 分 · 字数 15 分 · 标题 10 分 · 图片 15 分 · 链接 0 分。标题 SERP 限制 70 字符；字数低于 150 警告，低于 60 失败；H2 和内部链接为可选项。','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'为 WooCommerce 产品自动检测。标题 20 分 · 元描述 30 分 · 字数 15 分 · 标题 5 分 · 图片 20 分 · 链接 0 分。标题 SERP 限制 70 字符；字数低于 80 警告，低于 40 失败；H2 和内部链接为可选项。','Available models reference'=>'可用模型参考','avg'=>'平均','Batch Analysis'=>'批量分析','Behavior'=>'行为','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'行为：选择 AI 预设（字面、平衡、创造性），添加全站自定义提示指令，启用或禁用自动保存后翻译，并配置翻译记忆库。','Block Content'=>'块内容','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'当当前页面以其源语言显示，且没有访客语言的翻译时，会显示一个礼貌的通知。由Lingua Forge路由器的LINGUAFORGE_LANG_FALLBACK_ACTIVE信号驱动——当请求区域存在翻译时不发出任何信号。','Block Editor'=>'块编辑器','block keywordfallback'=>'回退','block keywordi18n'=>'国际化（i18n）','block keywordlanguage'=>'语言','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'翻译','Block locking'=>'块锁定','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'为自定义文章类型注册的块模式。使用“翻译”按钮生成语言变体。翻译内容保存在此处，可从块编辑器的模式插入器复制到任何CPT文章中，或用作同步模式（可重用块）的起点。','block titleMissing Translation Notice'=>'缺少翻译通知','Block translation reuses'=>'块翻译重用','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'块级翻译缓存在帖子之间共享。启用时，相同的块（相同的标记、语言对和词汇表）将从内存中提供，而不是再次调用AI。词汇表编辑和合规预设更改会自动使受影响的缓存翻译失效。','Blog / Editorial'=>'博客 / 编辑','Blog / Editorial (default)'=>'博客 / 编辑（默认）','Blog Home'=>'博客首页','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'博客文章使用Article；所有其他类型的帖子和页面使用WebPage。包括标题、描述、inLanguage、url、发布时间、修改时间、图片和发布者。','Browser language redirect'=>'浏览器语言重定向','Built-in preset instructions:'=>'内置预设指令：','Bulletize (•-prefixed)'=>'项目符号（•-前缀）','cached'=>'已缓存','Cached API responses'=>'缓存的 API 响应','Cached block translations'=>'缓存的块翻译','Cancel'=>'取消','Cannot determine target language from slug.'=>'无法从slug中确定目标语言。','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'无法写入产品 %1$d：它是一个翻译版本（语言：%2$s）%3$s。操作数据（价格、库存、SKU、尺寸）必须在源产品上更新。通过以下方式解决源产品ID：GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'规范标签','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'限制网站生成的AI使用量，并限制哪些用户角色可以触发付费AI调用。位于每用户速率限制（每分钟30请求，硬编码）之上，已保护免受单一用户无限循环的影响。','Cart'=>'购物车','chars'=>'字符数','Check your account, billing, or remaining credits directly on the provider console:'=>'在提供商控制台直接检查您的账户、账单或剩余额度：','Checkout'=>'结账','Chunk translated'=>'已翻译的块','Chunk translated to:'=>'已翻译的块：','Clear'=>'清除','Clear All'=>'全部清除','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'清除所有缓存的 AI 结果？未来请求将触发新的 API 调用，直到缓存重建。','Clear API Response Cache'=>'清除 API 响应缓存','Clear Debug Files'=>'清除调试文件','Clear hints'=>'清除提示','Clear input'=>'清除输入','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'清除整个翻译记忆？未来的翻译将重新构建缓存。','Clear Translation Memory'=>'清除翻译记忆','Close'=>'关闭','Close language panel'=>'关闭语言面板','Close popover'=>'关闭弹出窗口','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'所有LF拥有的条目在$wp_rewrite->extra_rules_top中的可折叠转储。用于诊断添加新语言后出现的404或路由冲突。','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'常见原因：全页缓存（清除它）、安全插件阻止 .txt 文件，或自定义的 Nginx/Apache 规则。该文件在每次请求时由 LF 提供服务——没有物理文件写入磁盘。','Compatibility'=>'兼容性','Compliance Preset'=>'合规预设','Configuration issue: WP site language has no content on this site'=>'配置问题：WP 网站语言在此网站上没有内容','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'在设置→API密钥中配置AI提供商以启用AI驱动的建议。','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'为你网站的每种语言配置 hreflang、Open Graph、Schema.org、站点地图和社交分享。以下每个部分处理多语言SEO的一个方面。','Configured'=>'已配置','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'确认永久链接结构与Lingua Forge路径路由兼容。不支持纯数字或普通结构。','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'自动排除Contact Form 7（wpcf7_contact_form）、Flamingo联系人和入站消息（flamingo_contact, flamingo_inbound）以及WordPress语言包同步存储（wp_sync_storage）。可在每行或逗号分隔中添加其他第三方帖子类型，内容不应被语言过滤。','Content generated'=>'内容已生成','Content Generator'=>'内容生成器','Content profiles and weights'=>'内容配置文件和权重','Content ready'=>'内容已准备好','Contributors and above — default (edit_posts)'=>'贡献者及以上——默认（编辑文章）','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'控制向AI发送的内容量以及响应的最大大小。留空使用内置默认值（显示为占位符）。如果页面内容被截断，请提高这些值；如果想降低API成本，请降低它们。','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'控制 Lingua Forge 如何与 WooCommerce 订单处理集成。','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'控制 AI 内容生成器功能的令牌预算和输入限制。留空字段以使用内置默认值。','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'控制管理员从插件→已安装插件→删除中删除插件时的行为。插件设置和AI缓存总是会被删除。默认会保留语言分配和翻译关系，以便意外卸载或重新安装时可以继续之前的状态。','Conversational'=>'对话性','Copied ✓'=>'已复制 ✓','Copied!'=>'已复制！','Copy'=>'复制','Copy and paste into a GitHub issue or support request.'=>'复制并粘贴到GitHub问题或支持请求中。','Copy failed — please copy the URL manually.'=>'复制失败——请手动复制URL。','Copy from source'=>'从源复制','Copy markup'=>'复制标记','Copy system info'=>'复制系统信息','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'将当前URL复制到剪贴板。成功后显示“链接已复制”的提示。','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'复制结果并粘贴到需要的地方（例如直接粘贴到脚注字段中）。','Copy to safe storage'=>'复制到安全存储','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'copy/native/auto JS操作：由LF的social-share.js处理','Copying…'=>'正在复制…','Could not add entry: source term and target term are required.'=>'添加条目失败：需要源术语和目标术语。','Could not copy the file. Check that the uploads folder is writable.'=>'无法复制文件。请检查上传文件夹是否可写。','Could not instantiate the provider.'=>'无法实例化提供者。','Could not save the file. Check that the uploads folder is writable.'=>'无法保存文件。请检查上传文件夹是否可写。','Could not save the glossary entry.'=>'无法保存词汇表条目。','Could not write to robots.txt. Check file permissions.'=>'无法写入robots.txt。请检查文件权限。','CPT Block Patterns'=>'CPT块模式','Create'=>'创建','Create missing'=>'创建缺失部分','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'为"%s"类型的文章创建翻译需要激活的集成。请确保已安装并激活所需的集成。','Creating…'=>'创建中…','Creative / Marketing'=>'创意 / 营销','Creative / Marketing instructions'=>'创意/营销指令','Current'=>'当前','Current content (will be overwritten)'=>'当前内容（将被覆盖）','Current status'=>'当前状态','Current title'=>'当前标题','Current: {current}'=>'当前：{current}','Currently emitting'=>'正在发出','Currently inherited from the %s constant. Selecting a value here will override it.'=>'目前继承自 %s 常量。这里选择的值将覆盖它。','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'目前跳过使用块注释属性占位符（如 wp:details summary 字段等）的文章——它们会走现有的单次调用翻译路径。','Currently:'=>'当前：','Custom'=>'自定义','Custom tables — LF post-meta filters do not affect orders.'=>'自定义表 — LF 文章元过滤器不影响订单。','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'每日AI配额已达上限（%1$d请求）。将在%2$s UTC重置。','Daily quota'=>'每日配额','Daily request limit'=>'每日请求限制','Danger Zone'=>'危险区域','Date'=>'日期','Debug Files'=>'调试文件','Debug files cleared. %d file was removed.'=>'调试文件已清除。%d 个文件已删除。' . "\0" . '','Debug Info'=>'调试信息','Debug logging'=>'调试日志','Debug logging disabled.'=>'调试日志已禁用。','Debug logging enabled.'=>'调试日志已启用。','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'调试：启用调试日志以捕获 AI 提示和 API 响应到本地文件。故障排除后禁用——调试模式会在每次 AI 请求时写入文件。','Default OG image'=>'默认OG图片','Default profile'=>'默认配置文件','Delete'=>'删除','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'是否删除调试目录中的所有.txt文件？目录本身将保持不变，以便未来的调试写入仍然可以正常存放。你也可以在wp-config.php中使用`define( \'LINGUAFORGE_AI_DEBUG\', true );`强制开启，此设置会覆盖切换。','Delete all files for this override (both .mo and .po)?'=>'是否删除此覆盖的所有文件（包括 .mo 和 .po）？','Delete content data on uninstall'=>'卸载时删除内容数据','Delete this glossary entry?'=>'是否删除此词汇表条目？','Describe what to write — topic, key points, structure…'=>'描述要写的内容——主题、重点、结构…','Destructive action — read before proceeding'=>'破坏性操作 — 阅读后再进行','Details ↗'=>'详细信息 ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'在运行时检测活跃的SEO插件（Yoast、Rank Math等）。当其他插件已输出完整的OG集时，仅发出og:locale + og:locale:alternate；当未检测到插件时，发出完整集。','Directory'=>'目录','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'仅在无头站点或完全自定义的hreflang实现中禁用。禁用后，LF不再删除WordPress核心的canonical标签，也不再屏蔽SEO插件的hreflang输出。','Disabled'=>'已禁用','Disabled (by setting)'=>'（通过设置）禁用','Disabled (mode setting)'=>'（模式设置）禁用','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'因为lf-social-share mu-plugin已经提供了此功能，所以禁用。','DISALLOW_FILE_MODS is set.'=>'设置了DISALLOW_FILE_MODS。','Display'=>'显示','Displays the Lingua Forge language switcher.'=>'显示Lingua Forge语言切换器。','Do not output any OG tags.'=>'不输出任何OG标签。','Documentation'=>'文档','Done'=>'完成','Done — {done} of {total} post(s) fixed.'=>'完成——已修复{done}个帖子（共{total}个）。','Down'=>'向下','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'直接从WordPress.org下载并安装WordPress核心语言包。安装后，区域成为URL路由和AI翻译工作流程的可用选项。可用语言列表按需获取——点击下面的按钮加载。','Dropdown direction'=>'下拉方向','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'每个指标产生四种状态之一：正常（全权重）、警告（50% 权重）、失败（0）、信息（0，无惩罚）。得分 ≥ 80 为绿色，50–79 为琥珀色，低于 50 为红色。','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'每篇文章根据六个基于规则的指标评分 0–100：标题、元描述、字数、标题结构、图片替代文本覆盖率和内部链接。阅读时间始终获得 10 分（仅供参考）。其余 90 分根据内容配置文件的不同，按不同权重分配（见下文）。','edit'=>'编辑','Editors and above (edit_others_posts)'=>'编辑者及以上（编辑他人文章）','Enable API response caching'=>'启用 API 响应缓存','Enable block-level translation cache reuse across posts'=>'启用跨文章块级翻译缓存重用','Enable Social Share URL rewriting for Social Icons blocks'=>'启用社交图标块的社交分享URL重写','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'当您的主题将文章标题渲染为 H2 而非 H1 时启用（某些块主题常见）。分析器会获取渲染后的页面，如果没有找到 H1 但找到 H2，则会将第一个 H2 提升为 H1 以进行评分。','Environment'=>'环境','environment variable'=>'环境变量','Error'=>'错误','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'每次分析文章时，得分会存储在文章元数据中。文章列表的“语言”列显示一个彩色编码的“SEO N”徽章，表示至少分析过一次。当存储两个得分时，会显示一个变化指示器（↑N / ↓N），显示自上次运行以来的变化。','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'必须恰好有一个 H1。H1 通常是由主题渲染的文章标题 — 如果可能，从实时渲染的页面读取，也可从文章内容作为备用。','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'支持的配置示例：WP站点语言=加泰罗尼亚语（CA），内容语言=CA + ES。','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'不支持的配置示例：WP站点语言=英语（EN），内容语言=CA + ES。英语不是内容语言，Lingua Forge无法将WP区域设置映射到任何翻译组。','Exclude from navigation menus'=>'从导航菜单中排除','Exclude from routing'=>'从路由中排除','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'从语言路由中排除此文章类型 — 其文章将不再显示在此处或接收 _lf_lang。这不能自动撤销。','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'从语言路由中排除此文章类型？其文章将不再出现在此列表中或接收 _lf_lang。您可以在 设置 → 路由器 → 查询过滤排除 中反转此操作。','excluded from routing'=>'已排除在路由之外','Excluded post types'=>'已排除的文章类型','Excluding…'=>'排除中…','Expand'=>'扩展','Expected: {expected}'=>'预期：{expected}','External share services'=>'外部分享服务','Extra guidance — tone, style, constraints, target audience…'=>'额外指导 — 语气、风格、约束、目标受众…','Extra guidance — tone, style, constraints…'=>'额外指导 — 语气、风格、约束…','Failed to save exclusion.'=>'保存排除失败。','Failed. Please try again.'=>'失败。请重试。','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'当页面没有特色图片、站点标志或站点图标时使用的备用图片URL。在存档、博客索引和没有缩略图的单一页面的社交预览中显示。','Feature'=>'功能','Featured Image Fixer'=>'特色图片修复器','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'功能分为两个层级。输入每个层级和提供者的确切模型标识符。留空使用内置默认（显示为占位符）。只有激活的提供者模型在运行时调用——如果计划切换，请提前配置其他模型。','File copied to safe storage successfully.'=>'文件成功复制到安全存储。','File modifications are disabled (DISALLOW_FILE_MODS).'=>'文件修改已被禁用（DISALLOW_FILE_MODS）。','Files'=>'文件','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'文件存放在以下目录中。用于诊断翻译问题——在你获得所需内容后关闭，以免文件堆积。你也可以在wp-config.php中使用`define( \'LINGUAFORGE_AI_DEBUG\', true );`强制开启，此设置会覆盖切换。','Filter'=>'筛选','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'按语言和帖子类型过滤，浏览内容，点击任何项目运行基于规则的SEO审计——标题长度、元描述、字数、标题结构、图片alt覆盖和内部链接。','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'使用linguaforge_debug_dir过滤，将调试输出重定向到非公共位置。','Finding'=>'查找','Fix'=>'修复','Fix All'=>'全部修复','Fix all links'=>'修复所有链接','Fix all parts'=>'修复所有部分','Fix Featured Images'=>'修复特色图片','Fix Links'=>'修复链接','Fix Nav'=>'修复导航','Fix Parts'=>'修复部分','Fix Template'=>'修复模板','Fix: go to'=>'修复：前往','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'修复存储在数据库中的所有LF脚手架FSE模板的站点编辑器命名空间和_lf_lang标签。更新早期版本Lingua Forge后运行一次——它将WooCommerce派生模板从活动主题组移动到WooCommerce组，并确保所有脚手架模板可被覆盖率报告发现。','Fixing {n} / {total}…'=>'正在修复{n} / {total}…','Fixing…'=>'修复中…','Flush Permalink Rules'=>'刷新永久链接规则','Flush Permalinks'=>'刷新固定链接','Flush Sitemap Cache'=>'刷新站点地图缓存','Footnote Content'=>'脚注内容','footnote(s) translated — applied together with content.'=>'脚注已翻译 — 与内容一同应用。','Footnotes'=>'脚注','Footnotes payload (advanced)'=>'脚注负载（高级）','Forbidden'=>'禁止访问','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'由wp-config.php中的LINGUAFORGE_AI_DEBUG常量强制关闭。删除该行即可从这里控制此切换。','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'由wp-config.php中的LINGUAFORGE_AI_DEBUG常量强制开启。删除该行即可从这里控制此切换。','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'强制在下一次请求时重新生成站点地图。批量导入或手动编辑翻译关系后使用。','Found <strong>{n}</strong> post(s) missing or out of sync with their source featured image, out of <strong>{scanned}</strong> scanned for <strong>{lang}</strong>.'=>'找到 <strong>{n}</strong> 篇文章的特色图像缺失或与源不同步，共扫描了 <strong>{scanned}</strong> 篇文章（语言：<strong>{lang}</strong>）。','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'发现错误或意外行为？请在GitHub上打开问题——包括上方的调试信息块和你预期与实际发生的简要描述。','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'在<强>{total}</强>个已扫描的帖子中发现<强>{parts}</强>个部分，涉及<强>{scanned}</强>个帖子，语言为<强>{lang}</强>。','From'=>'来自','Front Page'=>'首页','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE 本地化：直接从此标签页搭建、翻译和修复全站编辑模板和模板部分中的链接。','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'从激活的主题播种的FSE模板。在站点编辑器中创建并自定义。','Full'=>'全部','Full Article'=>'完整文章','Full post'=>'完整帖子','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'全页翻译使用 JSON 架构限制的输出。这需要安装并激活连接器插件（不仅仅是在设置→连接器中保存 API 密钥）。如果翻译失败，请检查 PHP 错误日志以获取具体错误，或切换到内置提供者。','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'全页翻译，内容生成器（中端模型已完全足够）','General'=>'通用','Generate'=>'生成','Generate Content'=>'生成内容','Generate content…'=>'生成内容…','Generate Excerpt'=>'生成摘要','Generate Meta Description'=>'生成元描述','Generate the multilingual sitemap at /lf-sitemap.xml'=>'在 /lf-sitemap.xml 生成多语言站点地图','Generated Content'=>'生成内容','Generated meta description'=>'生成的Meta描述','Generating…'=>'生成中…','Generation failed.'=>'生成失败。','Getting started'=>'入门','Global AI preset'=>'全局 AI 预设','Global default (%s)'=>'全局默认 (%s)','Glossary'=>'词汇表','Glossary entry added.'=>'词汇表条目已添加。','Glossary entry removed.'=>'词汇表条目已删除。','Glossary Tab'=>'词汇表标签','Google (Gemini)'=>'Google（Gemini）','Google AI Studio'=>'Google AI Studio','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google 不参与 IndexNow。它通过 robots.txt 中的 Sitemap: 指令发现网站地图 — LF 已经配置过了。使用 Google Search Console 监控索引覆盖率。','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'启用 H2 作为 H1 模式 — 标题计为 H1 等价（无法从渲染页面检测到标题标签；请确认您的主题正确输出标题）。','Heading structure rules'=>'标题结构规则','Headings'=>'标题','Hide'=>'隐藏','High-Performance Order Storage (HPOS)'=>'高性能订单存储（HPOS）','Hints'=>'提示','Home link text'=>'主页链接文本','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'在翻译中应如何显示。输入与源术语相同的值，以指示AI逐字保留。','How to use'=>'使用方法','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT 同步 — 过渡期；LF 文章元过滤器应用于 CPT 复制。','Hreflang'=>'hreflang','Hreflang output'=>'hreflang输出','Hreflang settings saved.'=>'hreflang设置已保存。','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'图标 + 标签','Icon only'=>'仅图标','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'如果勾选，卸载插件将永久删除所有语言分配、翻译关系、元描述、每页预设、AI词汇表和每个帖子的翻译记忆。这无法撤销。除非你完全移除网站的多语言支持，否则请不要勾选。','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'如果你安装了通用SEO插件，此面板显示LF如何适应以避免重复输出。目标是避免冲突——而非合作。LF始终提供多语言SEO层（hreflang、og:locale、inLanguage schema），这需要了解LF的语言路由配置以正确生成。','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'如果你安装了Yoast SEO、Rank Math、All in One SEO或SEOPress，Lingua Forge会检测到它们并调整以避免重复输出。对于hreflang，LF完全接管并抑制插件的输出，因为这些插件无法为多语言路由配置生成正确的hreflang。对于Open Graph，LF只添加og:locale和og:locale:alternate——多语言信号，这是插件无法提供的——并将基础OG集留给插件。对于Schema.org，LF完全禁用自己的输出以避免冲突的JSON-LD图表。','Images'=>'图片','Improve writing'=>'改进写作','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'在块编辑器中，添加一个社交图标块。对每个图标，打开链接设置并输入以下"share:"值之一作为URL。在前端，LF会用当前页面的正确分享URL替换它。','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'包括名称、描述、inLanguage、url、图片，以及带有价格、货币和可用性的Offer。价格和可用性来自源语言产品（共享库存模型）。','Includes site name, url, and inLanguage.'=>'包括站点名称、网址和inLanguage。','IndexNow'=>'IndexNow','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'IndexNow 引擎在接受提交前会验证密钥文件。如果文件无法访问，提交将被拒绝并返回 403 错误。','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow 是一种由 Bing、Yandex 和其他搜索引擎支持的开放协议。当翻译的帖子发布或更新时，Lingua Forge 会自动通知所有参与的引擎一次性推送——无需轮询，也无需等待下一次 robots.txt 爬取。','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow 取代了已弃用的 Bing 和 Yandex 的站点地图推送端点。Google 通过 robots.txt 中的 Sitemap 指令发现站点地图，方式与以前相同。','Informative'=>'信息性','Input tokens'=>'输入令牌','Install'=>'安装','Install a Language'=>'安装语言','Installed SEO plugins'=>'已安装的SEO插件','Installing…'=>'安装中…','instock / oos / pending from WC stock status'=>'来自WC库存状态的库存/缺货/待处理','Instructions (optional)'=>'指示（可选）','Instructions / key points'=>'说明 / 重点','Insufficient permissions.'=>'权限不足。','Integration API'=>'集成 API','Internal Link Fixer'=>'内部链接修复器','Introduction only'=>'仅介绍','Invalid API key — double-check the key entered in the AI Provider settings.'=>'API 密钥无效 — 请再次检查在 AI 提供商设置中输入的密钥。','Invalid file reference.'=>'文件引用无效。','Invalid filename.'=>'文件名无效。','Invalid language code.'=>'无效的语言代码。','Invalid language.'=>'无效的语言。','Invalid locale code.'=>'无效的区域代码。','Invalid or primary language.'=>'无效或主要语言。','Invalid post ID.'=>'无效的帖子ID。','Invalid post type.'=>'无效的帖子类型。','Invalid taxonomy.'=>'无效的分类法。','Invalid template part.'=>'无效的模板部分。','Invalid template type.'=>'无效的模板类型。','JavaScript-powered actions'=>'JavaScript驱动的操作','Just now'=>'刚刚','Key could not be generated. Check that the site has write access to WordPress options.'=>'无法生成密钥。请检查站点是否具有对 WordPress 选项的写入权限。','Key file served automatically at: %s'=>'密钥文件自动提供：%s','Key file status'=>'密钥文件状态','Key points, ideas, or structure to build from…'=>'关键点、想法或结构基础…','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'密钥在静态存储时使用AES-256-GCM加密，配合站点特定的秘密（LINGUAFORGE_SECRET）。在未轮换秘密前，不要分享数据库导出。','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'密钥在存入WordPress数据库前会用AES-256-CBC加密。加密密钥来自您的WordPress认证盐（wp-config.php），因此明文密钥永远不会触及数据库。','Landing / Short-form'=>'着陆页 / 短格式','Language'=>'语言','Language %s installed successfully.'=>'语言%s已成功安装。','Language (optional)'=>'语言（可选）','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'此服务器禁用语言安装（设置了DISALLOW_FILE_MODS）。','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'此服务器禁用语言安装。wp-config.php中设置了DISALLOW_FILE_MODS常量。通过WP-CLI手动安装语言包：wp language core install de_DE','Language label'=>'语言标签','Language Overrides'=>'语言覆盖','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'语言覆盖：管理 Lingua Forge UI 字符串的自定义 .po/.mo 覆盖文件。请使用此方法而不是直接编辑插件文件——覆盖在更新后依然有效。','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'语言包安装失败。可能是已安装该语言、区域代码错误，或服务器阻止文件写入。','Language Setup'=>'语言设置','Language Switcher'=>'语言切换器','Language switcher'=>'语言切换器','Language uninstalled. %d post deleted.'=>'语言已卸载。%d个帖子已删除。' . "\0" . '','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'主题模板部分的特定语言副本。脚手架完成后，模板会更新以引用特定语言的部分。','Language:'=>'语言：','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'路由器当前已知的语言（由已安装的WordPress区域包和主要语言派生）。在下面的部分安装额外的语言包，以使更多语言可用于路由和翻译。','Last 30 days'=>'过去30天','Last 7 days'=>'过去7天','Last generated: %s'=>'最后生成：%s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'上次基于规则的SEO评分。请在设置 → SEO → 分析中运行分析以更新。','Last run: %s ago'=>'上次运行：%s 前','Lead paragraph (≤60 w)'=>'引导段（≤60字）','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'留空模型字段以使用该层的内置默认值。占位符显示将使用哪个模型。','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'对于品牌名称和应无论翻译自哪种语言都应强制保留的术语，留空即可。','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'留空以将此条目应用于所有目标语言——非常适合品牌名称、缩写和必须逐字保留的术语。','Leave blank to keep the existing key. Enter a new value to replace it.'=>'留空以保持现有密钥。输入新值以替换它。','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'留空以使用内置默认值。清除已保存的覆盖将恢复默认值，下一次保存时生效。','Legacy lf-social-share mu-plugin'=>'旧版lf-social-share mu-plugin','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'检测到旧版lf-social-share mu-plugin。LF将基础OG集推迟到mu-plugin，并仅输出og:locale + og:locale:alternate。你可以停用mu-plugin——LF内置的社交分享（SEO → 社交分享标签）和Open Graph覆盖了相同的功能。','Legacy post-based (CPT)'=>'传统基于文章（CPT）','Legal / Compliance'=>'法律 / 合规','Legal / Compliance instructions'=>'法律/合规指令','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF始终添加og:locale和og:locale:alternate——这是多语言OG信号，没有通用SEO插件能正确生成。对于基础OG集（og:title、og:description、og:image），当没有其他插件时，LF会输出。当安装了SEO插件，LF会跳过基础集以避免重复标签——不是因为插件“更好”，而是重复没有价值。','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF用xhtml:link交替生成自己的站点地图，涵盖所有翻译组。当安装了SEO插件，它会生成一个单独的站点地图——两者独立共存。将两者提交到Google Search Console：SEO插件的站点地图用于内容发现，LF的站点地图用于语言关系信号。','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF 正在输出 hreflang 标签，并且正在用自引用规范标签替换 WordPress 核心规范标签，以用于每个语言版本。','LF is suppressing hreflang output from: %s'=>'LF正在抑制以下内容的hreflang输出：%s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF为每个配置的语言（包括x-default）输出准确的hreflang。通用SEO插件无法访问你的LF路由配置，可能会基于错误的URL假设生成hreflang。LF通过过滤器抑制它们的输出以防冲突。','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF输出带有inLanguage注释的多语言JSON-LD，绑定到其语言路由配置。当安装了SEO插件，LF会完全禁用自己的schema：重复的JSON-LD图表会产生验证错误，也没有干净的方式补充现有图表。','LF provides'=>'LF提供','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF 移除 WordPress 核心的规范标签，并用指向正确语言前缀 URL 的自引用规范标签替换。当启用第三方 SEO 插件（如 Yoast、Rank Math、AIOSEO、SEOPress）时，LF 会完全将规范管理委托给该插件。','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF拥有的条目目前已在$wp_rewrite->extra_rules_top中注册。用于诊断404或路由冲突。提交错误报告时请复制这些内容。','Light'=>'轻量','Light (default — fast and cost-effective)'=>'轻量（默认——快速且成本效益高）','Light (fast and cost-effective — Haiku / Flash)'=>'轻量（快速且成本效益高——Haiku / Flash）','Light model'=>'轻量模型','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'轻量：用于元描述和摘要生成——快速、低成本。','Limit results to pages in the given Lingua Forge language code.'=>'限制结果仅显示给定Lingua Forge语言代码的页面。','Limits'=>'限制','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge 为您的 WordPress 站点添加多语言路由、AI 驱动的翻译、hreflang SEO 标签和语言切换器。','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge为产品页面添加了WooCommerce特定的Open Graph属性，以便在Facebook、Pinterest等平台分享产品链接时，显示正确的产品类型、价格和库存状态。','Lingua Forge AI Tools'=>'Lingua Forge AI工具','Lingua Forge AI Usage Statistics'=>'Lingua Forge AI 使用统计','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge扩展了WordPress核心的社交图标块，加入了动态分享URL。将任何图标的链接设置为"share:"值，LF在渲染时会将其重写为正确的分享URL或JavaScript操作——无需自定义代码或第三方插件。','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge在/lf-sitemap.xml生成专用的XML站点地图，为所有翻译内容添加语言备用链接。此站点地图补充了WordPress核心站点地图和任何SEO插件的站点地图——它不会取代它们。','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge是一个完整的多语言SEO解决方案。无需额外的SEO插件。','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge是一个完整的多语言SEO解决方案。无需额外的SEO插件或站点地图插件。','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge为每个配置的语言在每个页面输出<link rel="alternate" hreflang>标签，包括指向源语言的x-default。这是Google和其他搜索引擎的主要多语言SEO信号——无需额外的SEO插件。','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge输出Open Graph和Twitter Card元标签，使分享的URL在社交平台上显示正确的语言、标题、描述和图片。','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge输出Schema.org JSON-LD结构化数据，让搜索引擎理解您的内容类型、语言和元数据。这是向Google和其他爬虫传达多语言内容中的inLanguage注释的主要方式。','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge 默认限制两个 Gutenberg 功能，以保持跨语言的编辑行为一致。当你需要完整的 Gutenberg / FSE 功能时，请在此选择加入。','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge 将次级 WP_Query 实例（侧边栏小部件、模板块、插件查找）范围限制在活动语言，通过注入 _lf_lang 元限制。此处列出的文章类型不受该限制 — 它们的查询始终不受过滤。','Lingua Forge Settings'=>'Lingua Forge 设置','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Lingua Forge 更新被阻止：下载主机 "%s" 不在允许列表中。','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Lingua Forge 更新被阻止：下载包的 SHA-256 与清单不匹配。文件可能已被篡改。','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge 使用两个独立的缓存层以避免重复的 AI API 调用。使用下面的标签页检查和管理每个缓存层。','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge使用两个独立的缓存层以减少重复的AI API调用：','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge 每个提供商使用两个模型层级：','Lingua Forge version'=>'Lingua Forge 版本','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — AI 使用统计','Lingua Forge — Quick Translate'=>'Lingua Forge — 快速翻译','Lingua Forge — Settings'=>'Lingua Forge — 设置','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forge内置的社交分享和Open Graph模块涵盖了mu-plugin提供的所有功能，以及多语言og:locale支持。您可以安全地停用mu-plugin。','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge、WordPress和PHP版本；激活的主题；URL结构；WP站点语言和主要内容语言。WP站点语言旁的红色指示器表示它不是活跃内容语言之一——请在设置→常规中修复。','Link copied'=>'链接已复制','link(s)'=>'链接','Links'=>'链接','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'列出任何激活的第三方SEO插件。Lingua Forge在这些插件存在时会调整输出——请参阅设置→SEO→兼容性，了解每个功能的详细情况。','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'列出没有_lf_lang元值的已发布帖子类型。缺少此标签的帖子对所有语言过滤器都是不可见的。使用修复按钮为它们标记源语言，或使用排除将其从语言路由中完全移除。','Load available languages'=>'加载可用语言','Load content'=>'加载内容','Loaded from cache.'=>'从缓存加载。','Loading…'=>'加载中…','Locale only'=>'仅限区域','Locked — a conflicting SEO plugin is active. See the notice above.'=>'已锁定——存在冲突的SEO插件。请参阅上方通知。','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate 将其自定义翻译存储在 wp-content/languages/loco/ 目录中——该位置可能在 WordPress 核心更新、插件重装或删除 Loco Translate 时被静默清除。将文件复制到此处会将它们移动到 Lingua Forge i18n-overrides 目录，该目录在所有这些事件中都能持续存在，并在每次请求时自动加载。','Loco Translate — Copy to Safe Storage'=>'Loco Translate — 复制到安全存储','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'允许触发AI功能的最低WordPress权限。对多作者站点收紧此权限可以防止贡献者或试用账户运行付费AI调用。通过`linguaforge_required_capability`过滤器覆盖每个功能。','Maintenance'=>'维护','Maintenance Tab'=>'维护标签','Make casual'=>'使其随意','Make concise'=>'使其简洁','Make formal'=>'使其正式','Manage your account, review usage, or top up credits:'=>'管理您的账户，查看使用情况，或充值：','Mark citations needed'=>'标记需要引用','Max context characters'=>'最大上下文字符数','Max hints characters'=>'最大提示字符数','Max input characters'=>'最大输入字符数','Max output tokens'=>'最大输出标记数','Maximum characters accepted from the input field. Default: 8 000.'=>'输入字段接受的最大字符数。默认：8000。','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'在未提供提示的情况下，传递给 AI 的现有帖子内容的最大字符数，作为种子上下文。默认：6000。','Maximum characters read from the Hints field. Default: 2 000.'=>'从提示字段读取的最大字符数。默认：2000。','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'转发给AI的最大字符数。0表示无限制——始终发送完整内容（推荐）。仅在提供商有严格的上下文窗口时设置非零值。内容被截断时，PHP错误日志会有警告。','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'AI在单次翻译响应中可能生成的最大标记数。如果翻译在末尾被静默截断，请增加此值。默认：16000。','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'每次生成运行，AI 可能生成的最大令牌数。如果完整文章被截断，请增加此值。默认：8192。','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'每次快速翻译，AI 可能生成的最大令牌数。默认：2000。','Meta Description'=>'Meta描述','Meta description'=>'Meta描述','Meta Description, Excerpt Generator'=>'元描述、摘要生成器','Meta Description, Excerpt Generator, quick translate'=>'元描述、摘要生成器、快速翻译','Metric'=>'指标','Minimum role'=>'最低角色','Missing'=>'缺失','Missing pattern name or language.'=>'缺少模式名称或语言。','Mode'=>'模式','Model'=>'模型','Model ID'=>'模型ID','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'模型选择由 WordPress 在 %s 管理——Lingua Forge 不为此提供者存储模型标识符。','Model tier'=>'模型层级','Model tiers'=>'模型层级','Models'=>'模型','Modified'=>'已修改','Most recent cached block'=>'最新缓存块','Most recent cached response'=>'最新缓存响应','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'多语言路由，完整的多语言 SEO（hreflang、Open Graph、Schema.org、站点地图），以及用于 WordPress 的 AI 内容工具。语言检测、URL 路由、翻译、内容生成和完整的 SEO 层 — 无需配套插件。','Multilingual SEO'=>'多语言SEO','Multilingual SEO overview'=>'多语言SEO概览','My Account'=>'我的账户','Name'=>'名称','Name displayed in this language. Leave empty to use the source name.'=>'在此语言中显示的名称。留空以使用源名称。','Navigation'=>'导航','Navigation has no content to translate.'=>'导航没有内容可翻译。','Navigation not found.'=>'未找到导航。','Navigation posts are translated via the Router tab, not this button.'=>'导航文章通过路由标签进行翻译，而不是通过此按钮。','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'导航翻译需要激活的AI提供商。在API密钥标签中配置API密钥。','Navigations'=>'导航','Network error — could not reach the provider: %s'=>'网络错误 — 无法连接到提供商：%s','Network error — could not reach the WordPress AJAX endpoint.'=>'网络错误 — 无法连接到 WordPress AJAX 端点。','Network error.'=>'网络错误。','Never run'=>'从不运行','No %s version found in this translation group.'=>'在此翻译组中未找到%s版本。','No active plugins detected.'=>'未检测到激活的插件。','No AI provider configured.'=>'未配置AI提供商。','No AI provider configured. Add an API key in Settings → API Keys.'=>'未配置AI提供商。在设置→API密钥中添加API密钥。','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'在所选时间窗口（%s）内未记录AI使用情况。请在上方选择更宽的时间范围。','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'尚未记录AI使用情况。一旦编辑器执行翻译、生成元描述或使用任何其他AI功能，统计数据将显示在这里。','No API key configured for this provider.'=>'此提供者未配置 API 密钥。','No API key configured — enter your key in the AI Provider settings.'=>'未配置 API 密钥 — 在 AI 提供商设置中输入您的密钥。','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'没有内置指令 — 每个 AI 功能使用其自己的调优默认值。请在下面的自定义提示指令字段中添加您的站点规则。','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'未检测到冲突的SEO插件。Lingua Forge独立处理所有SEO输出。','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'没有剩余额度 — 在 platform.openai.com/account/billing 充值您的 OpenAI 账户。','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'尚未找到自定义 Loco Translate 文件。保存翻译后，它们会显示在这里。','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'未检测到外部OG插件。LF输出完整的OG + Twitter Card集。','No file was selected.'=>'未选择文件。','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'没有符合当前筛选条件的词汇表条目。清除筛选以查看所有条目，或在下方添加新条目。','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'还没有词汇表条目。请在下方添加以开始在翻译中强制执行术语。','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'未找到H1。通常文章标题即为H1——请确认您的主题是否输出了它。','No images found in content.'=>'内容中未找到图片。','No internal links found to update.'=>'未找到要更新的内部链接。','No key'=>'无密钥','No language-specific template parts found to map.'=>'未找到要映射的特定语言模板部分。','No LF meta description set — using excerpt/content.'=>'未设置LF元描述——使用摘要/内容。','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'未找到LF重写规则。如果这是意外的，请刷新固定链接。','No links found.'=>'未找到链接。','No links found. Internal links improve crawlability and user navigation.'=>'未找到链接。内部链接有助于爬行和用户导航。','No meta description found. Generate one via the AI meta description feature.'=>'未找到元描述。请通过AI元描述功能生成。','No navigation references needed updating.'=>'无需更新的导航引用。','No override files uploaded yet.'=>'尚未上传任何覆盖文件。','No PHP limit'=>'无 PHP 限制','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'未找到实际的robots.txt文件。WordPress虚拟生成它，LF的站点地图指令已自动包含其中。','No published posts found for the selected filters.'=>'未找到符合筛选条件的已发布文章。','No response from AI provider. Check your API key and try again.'=>'未收到AI提供商的响应。请检查您的API密钥并重试。','No response from provider — check the error log for details.'=>'没有收到提供者的响应 — 请检查错误日志以获取详细信息。','No secondary languages configured.'=>'未配置次要语言。','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'未配置次要语言。请在上方安装语言包以启用模板脚手架。','No source content found to translate.'=>'未找到可翻译的源内容。','No source page linked yet.'=>'尚未链接源页面。','No template part references needed updating.'=>'无需更新的模板部分引用。','No terms found.'=>'未找到术语。','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'没有可用的文本生成模型。请在 设置→连接器 中配置 AI 提供者。','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'未检测到第三方SEO插件。Lingua Forge处理所有多语言SEO输出。','No title set.'=>'未设置标题。','No translated content found. The sitemap will populate once posts have been translated.'=>'未找到翻译内容。一旦文章被翻译，站点地图将会填充。','No translated URLs found to submit. Publish some translated posts first.'=>'未找到要提交的翻译 URL。请先发布一些翻译的帖子。','No translation found — analyzed the source language version.'=>'未找到翻译——已分析源语言版本。','No user message found in the message array.'=>'消息数组中未找到用户消息。','No {lang} translation registered (TRID missing)'=>'未注册{lang}翻译（TRID缺失）','No — WooCommerce integration class not loaded'=>'未加载WooCommerce集成类','Noindex (hide this language version from search engines)'=>'不索引（在搜索引擎中隐藏此语言版本）','None'=>'无','Normalize order line item product IDs to the source-language product at checkout'=>'在结账时将订单行项目的产品 ID 标准化为源语言的产品ID','not a content language — see notice above'=>'非内容语言——见上方通知','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'尚未生成。站点地图在首次访问站点地图URL时构建，并缓存24小时。','Notes'=>'备注','Nothing — all types disabled'=>'无——所有类型均已禁用','Notice message'=>'通知信息','Notice settings'=>'通知设置','Numeric permalink structure is not supported.'=>'不支持数字永久链接结构。','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card标签：由LF的Open Graph模块（SEO → Open Graph & Twitter Cards）处理','Oldest cached block'=>'最旧缓存块','Oldest cached response'=>'最旧缓存响应','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'一键复制涵盖上述所有部分的纯文本系统摘要。将其粘贴到GitHub问题或支持请求中，以便一览完整环境。','Only .mo files are accepted.'=>'只接受 .mo 文件。','Open an issue →'=>'打开问题→','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph 和 Twitter 卡片','Open Graph output'=>'Open Graph输出','Open Graph settings saved.'=>'Open Graph设置已保存。','Open Search Console →'=>'打开搜索控制台→','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'打开浏览器的原生Web分享界面（iOS、Android、部分桌面）。如果不支持，则回退到剪贴板复制。','OpenAI (GPT)'=>'OpenAI（GPT）','OpenAI Platform'=>'OpenAI 平台','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'编辑者的可选上下文（例如“ASIC = 应用特定集成电路；在技术上下文中保留英文”）。','Order line item source mapping'=>'订单行项目源映射','Order placed in language: %s'=>'订单语言：%s','Order storage'=>'订单存储','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'在 wp_posts 中的订单——确保 shop_order 被排除在 LF 路由之外。','Output'=>'输出','Output Article or WebPage schema on singular posts and pages'=>'在单篇文章或页面上输出Article或WebPage架构','Output hreflang tags in wp_head'=>'在wp_head中输出hreflang标签','Output mode'=>'输出模式','Output Open Graph tags in wp_head'=>'在wp_head中输出Open Graph标签','Output Product schema on WooCommerce product pages'=>'在WooCommerce产品页面输出Product架构','Output Schema.org JSON-LD in wp_head'=>'在wp_head中输出Schema.org JSON-LD','Output tokens'=>'输出令牌','Output WebSite schema on the front page and blog index'=>'在首页和博客索引页输出WebSite架构','Overall SEO score'=>'整体SEO评分','overridden'=>'已覆盖','Override file deleted.'=>'覆盖文件已删除。','Override file uploaded successfully.'=>'覆盖文件上传成功。','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'覆盖此页面的AI预设，用于翻译和内容生成。所有其他功能始终使用全局预设。','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'覆盖此页面的AI预设，用于翻译和内容生成。站点范围的自定义提示指令（设置 → 行为）始终会附加到每个请求，无论此选择如何。','Overview'=>'概览','Page'=>'页面','Part'=>'部分','Paste a footnote, sentence, or any snippet here…'=>'在此粘贴脚注、句子或任何片段…','Paste text, or select text in the editor first…'=>'粘贴文本，或先在编辑器中选择文本…','Paste text, or select text on the page first…'=>'先粘贴文本，或在页面上选择文本…','Paste your API key…'=>'粘贴您的API密钥…','Path prefix (/de/)'=>'路径前缀 (/de/)','Path prefix — example.com/de/'=>'路径前缀——example.com/de/','Path routing requires a post-name based permalink structure. Change it in'=>'路径路由需要基于文章名称的永久链接结构。在','Pattern'=>'模式','Pattern has no content to translate.'=>'模式没有内容可翻译。','Pattern not found.'=>'未找到模式。','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'模式已翻译并保存。通过块编辑器模式插入器将内容复制到您的CPT帖子中，或用作可重用块的起点。','Pattern translation failed.'=>'模式翻译失败。','Payment required — your account has no remaining credits.'=>'需要付款——您的账户余额已用尽。','Per-Post Analysis'=>'每篇分析','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'每篇缓存用于AI生成的翻译、元描述、摘要和内容。当内容或AI提供者/模型发生变化时，条目会自动失效。','Permalink rules flushed successfully.'=>'永久链接规则已成功刷新。','Permalink Structure'=>'永久链接结构','Permalink structure is compatible with Lingua Forge path routing.'=>'永久链接结构与Lingua Forge路径路由兼容。','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'永久删除与此语言相关的所有模板、模板部分、模式、导航菜单、文章、页面、自定义文章类型、产品和产品变体。同时删除WordPress区域包文件，使此语言不再出现在路由器中。此操作无法撤销。','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'永久卸载 %s 吗？这将删除此语言的所有翻译内容，且无法撤销。','Permission denied.'=>'权限被拒绝。','Persuasive'=>'说服性','PHP constant'=>'PHP 常量','PHP max_execution_time'=>'PHP最大执行时间','PHP memory_limit'=>'PHP内存限制','PHP version'=>'PHP版本','Pin on Pinterest'=>'在Pinterest上钉住','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'固定术语，不能翻译或必须始终以特定方式呈现（例如品牌名、产品名、缩写）。词汇表约束会注入到每个 AI 翻译请求中，适用于所有功能：帖子翻译、元描述、摘要和 FSE 模板翻译。','Plain language'=>'简明语言','Plain permalinks are not supported.'=>'不支持纯粹的永久链接。','Please enter some instructions first…'=>'请先输入一些说明…','Please enter some text first…'=>'请先输入一些文本…','Plugin'=>'插件','Post'=>'帖子','Post not found or not published.'=>'未找到或未发布的文章。','Post not found.'=>'未找到帖子。','Post on X / Twitter'=>'在X / Twitter上发布','Post type'=>'文章类型','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'用逗号或换行符分隔的帖子类型别名。保存后立即生效——无需刷新永久链接。','Post Types'=>'文章类型','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'没有_lf_lang的文章对所有Lingua Forge语言过滤器都是不可见的。这可能发生在内容导入或在插件激活之前创建内容时。','Prefilled from excerpt. Edit to override.'=>'预填自摘录。编辑以覆盖。','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'价格和可用性始终反映源语言产品（共享库存模型）。仅在LF的Open Graph模块设置为“完整”或“自动”模式且未检测到冲突的SEO插件时输出标签。','Primary content language'=>'主要内容语言','Primary Language'=>'主要语言','Primary language'=>'主要语言','Primary language saved.'=>'主要语言已保存。','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'主要语言：您的现有内容所用的语言。所有翻译都以此语言为基础；更改它不会移动或删除任何帖子。','Processing…'=>'处理中…','Product'=>'产品','Product / eCommerce'=>'产品 / 电子商务','Product Open Graph'=>'产品Open Graph','Product — WooCommerce product pages'=>'产品——WooCommerce产品页面','Profile'=>'个人资料','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'配置文件会根据所分析内容的类型调整阈值和权重。配置文件会自动解析；您可以在分析运行时从下拉菜单中覆盖它。','Provider'=>'提供者','Provider error (HTTP %1$d): %2$s'=>'提供者错误（HTTP %1$d）：%2$s','Provider returned no response. Check the WordPress error log for details.'=>'提供者未返回响应。请检查 WordPress 错误日志以获取详细信息。','Provider service temporarily unavailable — try again in a moment.'=>'提供者服务暂时不可用——请稍后再试。','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'将每个已发布、由 LF 管理的 URL 一次性推送到 IndexNow。自动提交已在每次发布/更新时运行——仅在批量导入后或首次设置 IndexNow 时使用。','Quality'=>'质量','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'质量（默认——Sonnet / GPT-4o / Gemini Pro）','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'质量（十四行诗 / GPT-4o / Gemini Pro）','Quality model'=>'质量模型','Quality: used for post translation and content generation — higher quality, higher cost.'=>'质量：用于帖子翻译和内容生成——更高质量，成本更高。','Query Filter Exclusions'=>'查询过滤排除','Quick Translate'=>'快速翻译','Quick Translation'=>'快速翻译','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'快速翻译用于片段/块模式——从工具栏、编辑器或块弹出窗口按需翻译短段落。它使用与全文翻译不同的轻量配置，以保持响应速度快且成本低。','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'请求频率限制——向提供者发送了过多请求；请稍等片刻后重试。','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'重新启用 Gutenberg 的 canLockBlocks。适用于需要防止贡献者移动或删除特定块的编辑模板。','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'重新启用 supportsTemplateMode。这是完整站点编辑工作流程的核心，适用于有意进行文章级模板覆盖的情况。','Re-generates and updates the cached result.'=>'重新生成并更新缓存结果。','Re-scan'=>'重新扫描','Re-scanning…'=>'重新扫描…','Re-translate'=>'重新翻译','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'当前安装的只读诊断。这里不更改任何设置——用于验证配置、发现问题和收集错误报告信息。','Reading time'=>'阅读时间','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'根据浏览器的Accept-Language头，将访客重定向到其偏好的语言版本','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'进一步优化——例如“使其更短”或“使用正式语气”…','Refine further:'=>'进一步完善：','Refinement'=>'完善（%d为完善迭代次数）','Refinement failed — please try again.'=>'完善失败——请重试。','Refining…'=>'正在完善…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'重新生成WordPress重写规则，以确保URL前缀、特定语言的别名和存档重写保持同步。更改主要语言或添加新语言支持后需要执行此操作。','Remove stored key'=>'移除存储的密钥','Repair failed.'=>'修复失败。','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'修复上述所有可路由帖子的标签，设置 _lf_lang = %s。路由排除的帖子类型不受影响。仅在导入内容后或首次激活时运行——不要用作批量语言重新分配工具。','Repair Template Metadata'=>'修复模板元数据','Repair template metadata'=>'修复模板元数据','Repair — assign _lf_lang = %s to all routable posts above'=>'修复——将 _lf_lang = %s 分配给所有上述可路由的帖子','Repairing…'=>'修复中…','Report an issue on GitHub'=>'在 GitHub 上报告问题','Request count'=>'请求计数','Request failed — please try again.'=>'请求失败——请重试。','Request failed.'=>'请求失败。','Request failed. Check your connection.'=>'请求失败。请检查您的连接。','Request failed. Please try again.'=>'请求失败。请再试一次。','Requests'=>'请求数','requests / day'=>'请求/天','Reset'=>'重置','Result will appear here…'=>'结果将显示在这里…','Retranslate'=>'重新翻译','Retranslating…'=>'重新翻译中…','Review carefully — links and slugs not updated.'=>'请仔细检查 — 链接和别名未更新。','Review translation before applying'=>'在应用前审查翻译','Revise'=>'修订','Revision'=>'修订','Revision Type'=>'修订类型','Rewrite Rules'=>'重写规则','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt已更新，包含站点地图指令。','Router'=>'路由器','Router Tab'=>'路由器标签','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'对所有已发布的文章进行一次完整的SEO审计，针对一个或所有激活的语言。得分会在每篇文章中保存，并在文章列表的语言列徽标中反映。','Run AI Analysis'=>'运行AI分析','Save'=>'保存','Save analysis settings'=>'保存分析设置','Save Debug Setting'=>'保存调试设置','Save Hreflang Settings'=>'保存Hreflang设置','Save Open Graph Settings'=>'保存Open Graph设置','Save Router Settings'=>'保存路由器设置','Save Schema.org Settings'=>'保存Schema.org设置','Save Settings'=>'保存设置','Save Sitemap Settings'=>'保存站点地图设置','Save Social Share Settings'=>'保存社交分享设置','Save the post to persist changes.'=>'保存帖子以持久化更改。','Save Uninstall Setting'=>'保存卸载设置','Save WooCommerce SEO Settings'=>'保存WooCommerce SEO设置','Saved to the meta description field when you apply.'=>'应用时保存到Meta描述字段。','Scan failed: '=>'扫描失败：','Scan request failed. Please try again.'=>'扫描请求失败。请重试。','Scanning posts for broken language links…'=>'扫描帖子以查找断链…','Scanning posts for missing or out-of-sync featured images…'=>'正在扫描文章中缺失或不同步的特色图像…','Schema output deferred.'=>'Schema输出已延迟。','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Schema.org输出','Schema.org settings saved.'=>'Schema.org设置已保存。','Score'=>'得分','Score computation'=>'得分计算','Score history and badges'=>'得分历史和徽章','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'得分是一个信号，而不是判决。一些内容在结构上有限制——非常短的页面、少正文的着陆页或以导航而非信息为目的的页面，天生得分可能较低。请使用此概览识别不同语言之间的真正差距，而不是追逐数字。','Search'=>'搜索','Search Results'=>'搜索结果','Sections'=>'部分','Security check failed — file path is not permitted.'=>'安全检查失败——文件路径不允许。','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'请参阅设置→SEO→兼容性，获取完整的每个功能行为表。','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'选择一种语言以管理其FSE模板、模板部分和导航菜单。','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'选择一篇文章，运行详细的SEO审计，以查看每个指标的结果和该项目的得分。','Select language'=>'选择语言','Send via Telegram'=>'通过Telegram发送','Send via WhatsApp'=>'通过WhatsApp发送','SEO'=>'SEO','SEO Analysis'=>'SEO分析','SEO character-count info'=>'SEO字符数信息','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'检测到SEO插件：%s。LF仅输出og:locale和og:locale:alternate；检测到的插件处理完整的OG集。','SEO Plugins'=>'SEO插件','SEO plugins and conflict avoidance:'=>'SEO插件和冲突避免：','SEO Score System'=>'SEO 得分系统','SEO Scores'=>'SEO 分数','SEO Tab'=>'SEO标签','Server setup (subdomain)'=>'服务器设置（子域名）','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'设置整个站点所有功能的默认 AI 行为。单个文章可以通过 Lingua Forge 元框覆盖此设置，用于翻译和内容生成。','Settings'=>'设置','Settings saved.'=>'设置已保存。','Settings → Connectors'=>'设置 → 连接器','Settings → General → Site Language'=>'设置→常规→站点语言','Settings → Permalinks'=>'设置→永久链接','Share on Facebook'=>'在Facebook上分享','Share on LinkedIn'=>'在LinkedIn上分享','Share on Mastodon'=>'在Mastodon上分享','Share via email (mailto:)'=>'通过电子邮件（mailto:）分享','Shared / compatibility mode'=>'共享/兼容模式','Shop'=>'商店','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'无论配置文件如何，简短内容（少于或等于3段）都不会因为缺少子标题而受到惩罚。简洁的页面不需要强制的标题结构。','Show home link'=>'显示主页链接','Shown when no translation exists for the visitor\'s language.'=>'当没有对应访客语言的翻译时显示。','Single'=>'单一','Single %s'=>'单一 %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'单词标题（%d字符）——添加第二个词可以提高清晰度和关键词覆盖率。','Single: %s'=>'单一：%s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'每个UTC日的全站AI请求上限（包括工具栏翻译和块修订）。计数器在UTC午夜重置。设置为0以禁用限制。','Sitemap'=>'站点地图','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'站点地图缓存已清除。将在下次访问站点地图URL时重新生成。','Sitemap output'=>'站点地图输出','Sitemap settings saved.'=>'站点地图设置已保存。','Sitemap URL'=>'站点地图URL','Size'=>'大小','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'社交图标块分享：URL：由LF内置的社交分享（SEO → 社交分享）处理','Social Share'=>'社交分享','Social Share settings saved.'=>'社交分享设置已保存。','Some link fixes failed.'=>'部分链接修复失败。','Some nav ref fixes failed.'=>'部分导航引用修复失败。','Some part fixes failed.'=>'部分修复失败。','Some parts could not be created.'=>'部分部分无法创建。','Some templates could not be created.'=>'部分模板无法创建。','Some translations failed.'=>'部分翻译失败。','source'=>'源','Source (EN)'=>'源术语','Source file not found.'=>'未找到源文件。','Source lang'=>'源语言','Source language'=>'源语言','Source term'=>'源术语','Source title'=>'源标题','Standard'=>'标准','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'标准使用每个功能的调优温度：翻译 T=0.2（精准），快速翻译 T=0.4，内容生成 T=0.6（创造性）。其他预设在所有功能中应用单一固定温度。','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'开始在任何字段中输入以查看模型建议，或使用下面的参考表。轻量级和中端质量模型（Haiku、GPT-4o mini、Gemini Flash）完全足够用于翻译和内容生成——旗舰“max”模型成本较高，结构化文本的质量提升有限。','Status'=>'状态','Status / Actions'=>'状态 / 操作','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'存储由内容哈希、语言对、提供者、模型和预设键控的原始AI响应。源帖子内容变更时，缓存条目会自动失效。可以在此清除单个帖子或全部缓存。','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'存储每个内容哈希的完整翻译后输出。启用（在行为中）。加快未变内容的重复翻译。当你想强制AI重新处理时，可以在此清除。','Storytelling'=>'讲故事','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'用于法律、监管、医疗或技术内容的严格保存模式。开启后，每个 AI 功能都使用较低的采样温度，并在系统提示中附加以下补充内容——术语、文章编号、单位、品牌名称和监管语言将逐字保留，而非意译。','Structured Outline'=>'结构化大纲','Subdomain (de.example.com)'=>'子域名（de.example.com）','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'子域名模式要求你的Web服务器将所有语言子域名（例如de.example.com）指向此WordPress安装。切换模式后，刷新永久链接规则并清除任何缓存。如果你的主页URL包含www（例如www.example.com），请使用lf_base_domain过滤器设置裸露的顶级域名，以确保子域名正确构建。','Subdomain — de.example.com/'=>'子域名——de.example.com/','Submit all URLs'=>'提交所有URL','Submit all URLs via IndexNow'=>'通过 IndexNow 提交所有 URL','Submit this URL to Google Search Console alongside your main sitemap.'=>'将此URL与您的主站点地图一起提交到Google搜索控制台。','Submit to Reddit'=>'提交到Reddit','Suggested meta description'=>'建议的元描述','Suggested title'=>'建议的标题','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'支持的提供者：Anthropic（Claude）、OpenAI（GPT）、Google（Gemini）。从下拉菜单选择活跃提供者——一次只用一个。输入API密钥以启用AI功能。','Suppressed: %s.'=>'已屏蔽：%s。','Switch to a post-name based structure in'=>'切换到基于文章名称的结构在','System'=>'系统','System Tab'=>'系统标签页','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'每个功能的 T=0.2–0.6','Tag'=>'标签','Tags emitted'=>'已发出的标签','Target lang'=>'目标语言','Target Language'=>'目标语言','Target language'=>'目标语言','Target term'=>'目标术语','Target: 140–160 chars for optimal SERP display'=>'目标：140–160字符以获得最佳SERP显示','Technical'=>'技术性','Technical / Scientific'=>'技术 / 科学','Technical / Scientific instructions'=>'技术/科学指令','Template "%s" already exists.'=>'模板“%s”已存在。','Template "{expected}" does not exist — create it in the Site Editor first.'=>'模板“{expected}”不存在——请先在站点编辑器中创建。','Template has no content.'=>'模板没有内容。','Template mode'=>'模板模式','Template not found or not stored in the database.'=>'未找到模板或未存储在数据库中。','Template part "%s" already exists.'=>'模板部分“%s”已存在。','Template part has no content.'=>'模板部分没有内容。','Template part not found or not stored in the database.'=>'未找到模板部分或未存储在数据库中。','Template Parts'=>'模板部分','Templates'=>'模板','Test connection'=>'测试连接','Testing…'=>'测试中…','Text domain / locale'=>'文本域 / 语言环境','Text to translate'=>'待翻译文本','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'API响应缓存存储每个AI请求的原始结果——翻译、元描述、摘要和内容生成——以输入的哈希值为键（内容、语言对、提供者、模型）。在调优提示或需要每个请求到达AI提供者时禁用。禁用不会删除缓存条目——重新启用会恢复它们。','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'每日配额（在行为→限制中配置）在此跟踪。当配额用尽，AI调用将暂停至次日。表格显示已用配额的比例。','The editor did not accept the content — please try again.'=>'编辑未接受内容——请重试。','The following directive is active in your virtual robots.txt:'=>'您的虚拟robots.txt中启用了以下指令：','The lf-social-share mu-plugin is active.'=>'lf-social-share mu插件已激活。','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu插件已激活。Lingua Forge内置的社交分享功能未激活——mu插件负责分享URL重写和JS操作。','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Light 级别使用上面模型表中配置的快速模型（默认：Haiku / Flash）。如果你需要与全页模式相同的翻译准确度，请切换到 Quality 级别。','The phrase as it appears in the source text.'=>'在源文本中出现的短语。','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'主要语言始终在你网站的根目录提供——在路径模式下没有URL前缀，在子域名模式下没有语言子域名。其他所有语言使用/语言/路径前缀（例如example.com/de/）或语言子域名（例如de.example.com），具体取决于下面的URL结构设置。','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → 兼容性标签显示实时检测状态，并详细说明LF在每个功能区域的具体操作。','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'分享URL始终反映当前页面——无需手动输入URL。linguaforge_social_share_url过滤器允许你覆盖任何服务的解析URL。','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'站点地图会在robots.txt中自动公告。所有主要搜索引擎——Google、Bing、Yandex——都能从robots.txt中发现它。无需手动提交。','The source page has no footnotes.'=>'源页面没有脚注。','The upload failed — please try again.'=>'上传失败——请重试。','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'使用情况表按功能（翻译、元描述、摘录、FSE模板、批量分析）、提供者和模型细分AI令牌消耗。使用日期范围按钮筛选今日、过去7天、过去30天或全部时间。','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'WordPress核心站点地图列出所有内容URL。LF站点地图通过xhtml:link hreflang交替链接告诉搜索引擎不同语言版本之间的关系。建议同时提交到Google搜索控制台以获得完整覆盖。','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'WordPress 网站语言 (%1$s) 映射到语言代码 "%2$s"，但此网站上没有帖子标记为 _lf_lang=%2$s。这会导致 WooCommerce 产品查询返回零结果、产品图像加载失败以及所有语言筛选内容查询中断。','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'WordPress 站点语言（设置 → 常规 → 站点语言）必须设置为您用于内容的语言之一——无论是主要内容语言还是次要语言。它不能是站点上没有内容的语言。','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'这些脚注来自源页面，仅供参考。请使用块编辑器将它们添加到此页面。','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'此目录会随着 Lingua Forge 的每次发布而更新。在 API 密钥标签中测试连接时，也会从提供者获取实时模型列表并刷新上述建议。','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'这是一个WooCommerce系统页面（商店、购物车、结账等）。其内容由WooCommerce管理——得分仅反映结构信号，而非用户可编辑的SEO内容。','This is the source page. Footnotes are edited directly in the block editor.'=>'这是源页面。脚注在块编辑器中直接编辑。','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'此密钥目前由服务器%s提供，无法在此处移除。请在上方输入新密钥以用数据库中的值覆盖它。','This language is protected and cannot be uninstalled.'=>'此语言受保护，无法卸载。','This language matches the WordPress instance locale and cannot be uninstalled.'=>'此语言与WordPress实例区域设置匹配，无法卸载。','Tier'=>'层级','Tip: to reset a model to the built-in default, clear the field and save.'=>'提示：要将模型重置为内置默认值，清空字段并保存。','Title'=>'标题','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'标题 15 分 · 元描述 20 分 · 字数 15 分 · 标题 20 分 · 图片 10 分 · 链接 10 分。标题在搜索结果中的限制为 60 个字符；元描述为 120–210 个字符；字数低于 300 时发出警告，低于 100 时失败；需要 H2；需要内部链接。','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'标题为 %1$d 个字符 — 可能在搜索结果中被截断（目标是少于 %2$d 个）。','Title is only %d chars — aim for at least 10 characters.'=>'标题仅为 %d 个字符 — 目标至少 10 个字符。','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'标题评分规则（所有配置文件）：为空时失败；少于 10 个字符时警告；只有一个词时警告；超过配置文件的搜索结果限制（博客为 60 字符，产品/落地页为 70 字符）时警告；至少有 10 个字符、至少有 2 个词且在搜索结果限制内则为正常。','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'要使用自定义加密密钥（而不是派生的 wp_salt 值），请将其添加到 wp-config.php：','Today'=>'今天','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'按功能、提供者和模型汇总的令牌消耗。每次成功的AI调用都会记录；测试连接的ping不计入总数。','Token usage'=>'令牌使用','Tone'=>'语调','tone'=>'语气','Tone:'=>'语气：','Too many AI requests. Please retry in %d seconds.'=>'请求次数过多。请在%d秒后重试。','Total'=>'总计','Total tokens'=>'总令牌','Translate'=>'翻译','Translate / Revise'=>'翻译/修订','Translate / Revise block'=>'块翻译/修订','Translate all'=>'全部翻译','Translate all %s terms (AI)'=>'翻译所有 %s 术语（AI）','Translate all categories (AI)'=>'翻译所有类别（AI）','Translate all labels (AI)'=>'翻译所有标签（AI）','Translate all tags (AI)'=>'翻译所有标签（AI）','Translate all terms (AI)'=>'翻译所有术语（AI）','Translate chunk'=>'翻译块','Translate Content'=>'翻译内容','Translate missing'=>'缺失翻译','Translate page…'=>'翻译页面…','Translated content'=>'翻译内容','Translated Labels'=>'已翻译标签','Translated Names'=>'已翻译的名称','Translated title'=>'翻译后的标题','Translated to:'=>'翻译为：','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'已翻译。在站点编辑器中查看——内部链接、导航URL和模板别名不会自动更新。','Translating…'=>'翻译中…','Translation Caching'=>'翻译缓存','Translation caching'=>'翻译缓存','Translation failed. Check the browser console.'=>'翻译失败。请检查浏览器控制台。','Translation found but permalink could not be generated'=>'找到翻译但无法生成永久链接','Translation Limits'=>'翻译限制','Translation Limits & Behavior'=>'翻译限制与行为','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'翻译限制：控制哪些用户角色可以触发AI翻译，并设置每月的令牌预算。超出预算后，AI调用将暂停，直到本月重置。','Translation Memory'=>'翻译记忆','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'翻译记忆库通过内容哈希、语言对、提供者和模型缓存AI结果。编辑帖子会使缓存条目失效，因此下一次翻译调用会获得新的结果。','Translation Memory cleared. %d cached block was removed.'=>'翻译记忆已清除。%d个缓存块已被移除。' . "\0" . '','Translation Memory setting saved.'=>'翻译记忆设置已保存。','Translation workflow'=>'翻译工作流程','Translation, Content Generator'=>'翻译、内容生成','Treat H2 as H1 equivalent'=>'将 H2 视为 H1 等价','Type'=>'类型','Uli Hake'=>'Uli Hake','Unexpected provider error (HTTP %d).'=>'意外的提供者错误（HTTP %d）。','Uninstall %s'=>'卸载%s','Uninstall Behaviour'=>'卸载行为','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'卸载行为：控制从插件 → 已安装插件 → 删除中删除的内容。插件设置和AI缓存始终会被删除。语言分配、翻译关系、元描述、词汇表和翻译记忆默认会保留，以便意外卸载或重新安装时可以继续。仅在完全从站点删除多语言支持时启用“卸载时删除内容数据”——此操作无法撤销。','Uninstall setting saved.'=>'卸载设置已保存。','unknown error'=>'未知错误','Unknown provider.'=>'未知提供者。','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'与hreflang不同——LF始终覆盖其他插件，因为它们无法知道您的多语言配置——Open Graph不同：Yoast、Rank Math等插件已为您的内容输出正确的OG标签。重复添加没有价值。在自动模式下，LF检测激活的SEO插件，只添加它们无法提供的内容：og:locale（当前语言）和og:locale:alternate（所有其他配置的语言）。','Unlimited'=>'无限','Up'=>'向上','Upload .mo file'=>'上传 .mo 文件','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'上传已编译的 .mo 文件以覆盖特定地区的第三方插件字符串——例如，使用“公寓”而非“房间”的自定义 VikBooking 翻译。文件必须遵循 WordPress 命名规范：{textdomain}-{locale}.mo（例如 vikbooking-ca.mo）。它们存储在上传文件夹中，并在插件更新时保持不变。','Upload Override'=>'上传覆盖','URL could not be mapped to a post — check the link target exists'=>'URL无法映射到帖子——请检查链接目标是否存在','URL structure'=>'URL结构','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL结构：路径前缀模式（例如.com/de/）无需更改服务器配置。子域名模式（de.example.com）需要通配符DNS记录、通配符SSL证书和Web服务器配置——请参阅服务器设置指南。','URL to enter'=>'输入的URL','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'可用时使用原生分享；否则回退到剪贴板复制。推荐用作“分享”按钮的默认设置。','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'使用本页面顶部的标签配置每个区域。对路由器标签的更改立即生效；对AI密钥和模型设置的更改将在下一次AI请求中应用。','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'每个语言对的用户管理术语表。条目会附加到翻译系统提示中，使 AI 始终使用偏好的术语——这对于领域词汇（“kWp”、“PPA”、“互联系点”）、不得翻译的品牌名和标准化的监管措辞至关重要。两个语言字段都是可选的：留空“源语言”以在任何翻译源语言时应用该条目；留空“目标语言”以同时应用于所有目标语言。','Using custom meta description.'=>'使用自定义Meta描述。','Using LF AI meta description.'=>'使用LF AI元描述。','Value source'=>'值来源','Verification key'=>'验证密钥','Version'=>'版本','View'=>'查看','View built-in default'=>'查看内置默认值','View current robots.txt'=>'查看当前robots.txt','View details'=>'查看详情','View Lingua Forge details'=>'查看Lingua Forge详情','Visit plugin site'=>'访问插件网站','Warning:'=>'警告：','WcPageBridge active'=>'WcPageBridge已激活','WebSite'=>'网站','WebSite — front page / blog index'=>'网站——首页/博客索引','What LF provides — and collision avoidance'=>'LF提供的内容——以及避免冲突的方法','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'LF提供：每个配置的语言的hreflang标签，带有og:locale和og:locale:alternate的Open Graph和Twitter卡片标签，带有inLanguage注释的Schema.org JSON-LD，以及位于/lf-sitemap.xml的专用多语言站点地图，含所有翻译组的xhtml:link交替条目。','When another SEO plugin is installed'=>'当安装了其他SEO插件时','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'启用调试日志（通过下面的切换或在 wp-config.php 中定义 LINGUAFORGE_AI_DEBUG），翻译和 FSE 模板翻译功能会将其原始 AI 提示和响应写入磁盘以进行故障排除。使用此部分监控输出，完成后清除——文件在大页面上可能快速增长。通过 linguaforge_debug_dir 过滤器配置目标目录。','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'启用时（推荐），存储在每个 WooCommerce 订单行项目上的产品 ID 会设置为源语言产品。这确保 total_sales 统计、WC Analytics 收入行和第三方 ERP 导出都引用每个 SKU 的一个产品 ID，而不是每个语言版本。权衡：订单邮件和我的账户中的“查看产品”链接会指向源语言页面。只有在连接系统依赖订单中的翻译产品 ID 时才禁用。可以使用 linguaforge_wc_order_item_source_mapping 过滤器进行每个项目的覆盖。','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'启用后，没有语言Cookie且URL中没有语言前缀的首次访问者将被重定向到最接近的匹配语言版本。如果浏览器首选语言不在激活的路由器语言中，则跳过重定向。一旦访客通过切换器选择了语言，Cookie将优先，未来的访问将忽略浏览器头信息。','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'启用后，Lingua Forge在产品页面输出以下附加元标签：og:type=product、og:price:amount、og:price:currency、og:availability，以及Facebook目录使用的它们的product命名空间等价标签。','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'启用后，站点地图URL会在robots.txt中自动公告，翻译内容保存时会刷新缓存。','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'当博客配置文件需要 H2 而未找到时，分析器会先检查 H3 子标题，然后发出警告。手风琴和详细信息块的标题默认为 H3；这些 H3 被视为有效结构，结果为正常，而非警告。','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'当WP站点语言不是内容语言时：WooCommerce产品查询在所有目录块中返回零结果；产品图片委托失败；所有按语言过滤的内容查询中断；语言切换器可能会显示一个虚假的非内容语言选项。如果在路由器或系统标签顶部看到红色配置警告，请先更正站点语言。','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'当Yoast SEO、Rank Math、All in One SEO或SEOPress激活时，Lingua Forge会通过过滤器自动屏蔽它们的hreflang输出。通用SEO插件基于单一语言URL结构生成hreflang，无法考虑您的多语言路由配置；LF的输出始终正确。','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'用于全文翻译的模型层级。质量使用上表中配置的模型，适合准确的长篇翻译。仅当速度或成本优先且内容较短时切换到轻量。','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'激活时，mu插件处理基础OG集，LF仅输出区域标签（自动模式）。移除后，LF会自动切换到完整的OG模式。','WooCommerce'=>'WooCommerce','WooCommerce Integration'=>'WooCommerce 集成','WooCommerce is not active.'=>'WooCommerce未激活。','WooCommerce page translations'=>'WooCommerce页面翻译','WooCommerce product price'=>'WooCommerce产品价格','WooCommerce SEO settings saved.'=>'WooCommerce SEO设置已保存。','WooCommerce store currency'=>'WooCommerce商店货币','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerce系统页面（商店、购物车、结账、我的账户）被排除在外——它们的内容由WooCommerce管理，不能通过SEO编辑进行改进。','WooCommerce version'=>'WooCommerce版本','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerce版本、订单存储模式（CPT / HPOS / 共享）以及四个内置WC页面（商店、购物车、结账、我的账户）的每语言翻译覆盖表。','Word count'=>'字数','WordPress AI Client (WP 7.0+)'=>'WordPress AI 客户端（WP 7.0+）','WordPress AI Client requires WordPress 7.0 or later.'=>'WordPress AI 客户端需要 WordPress 7.0 或更高版本。','WordPress AI Client — requirements:'=>'WordPress AI 客户端——要求：','WordPress Connectors'=>'WordPress 连接器','WordPress version'=>'WordPress版本','WP core canonical active (hreflang disabled)'=>'WP核心规范化（hreflang禁用）已激活','WP instance language'=>'WP 实例语言','WP site language requirement'=>'WP站点语言要求','WP-CLI reference'=>'WP-CLI参考','Write AI prompts and responses to disk for troubleshooting'=>'将AI提示和响应写入磁盘以进行故障排除','XML Sitemap'=>'XML站点地图','Yes'=>'是','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'你也可以将键定义为常量或环境变量（例如在 wp-config.php 中）。当没有存储数据库键时，这些来源会自动用作后备方案。','You do not have permission to manage these settings.'=>'您没有权限管理这些设置。','You do not have permission to read this post.'=>'你没有权限阅读此帖子。','{n} stale path(s)'=>'{n}个过时路径','~%d min read'=>'~%d分钟阅读' . "\0" . '','— AI features are disabled.'=>'— AI 功能已禁用。','— Any source language —'=>'— 任意源语言 —','— Any target language —'=>'— 任意目标语言 —','— Any target —'=>'— 任意目标 —','— Any —'=>'— 任意 —','— Auto-detect —'=>'——自动检测——','— auto-detect —'=>'— 自动检测 —','— Deferred to plugin'=>'——推迟到插件','— Disabled'=>'——已禁用','— Not detected'=>'——未检测到','— select a language —'=>'— 选择一种语言 —','← Back'=>'← 返回','↑ Detected from current post'=>'↑ 从当前帖子检测到','→ Locale tags only (manual setting)'=>'→ 仅限区域标签（手动设置）','→ Locale tags only — deferring base OG to plugin'=>'→ 仅限区域标签——将基础OG推迟到插件','↺ Re-translate'=>'↺ 重新翻译','↺ Refine'=>'↺ 重新完善','↺ Refresh'=>'↺ 刷新','↺ Refresh AI Analysis'=>'↺ 刷新 AI 分析','↺ Refreshing…'=>'↺ 正在刷新…','⚠ Borderline'=>'⚠ 边界线','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ 未找到<强>{lang}</强>帖子。确保所有翻译帖子在“语言”元框中将其语言元设置为<强>{lang}</强>。','⚠ No changes'=>'⚠ 无更改','⚠ No changes — re-scan?'=>'⚠ 无更改——重新扫描？','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ 所有 <strong>{lang}</strong> 的特色图片已与其源帖子同步。扫描了 <strong>{scanned}</strong> 个帖子。','✅ Copied'=>'✅ 已复制','✅ Fixed ({n})'=>'✅ 已修复（{n}）','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ 未发现<强>{lang}</强>的断链或模板不匹配。已扫描<强>{scanned}</强>个帖子和页面——所有检查通过。模板部分链接（头部、底部、侧边栏）未包括在内——请使用“修复模板部分”按钮单独检查。','✅ Template fixed'=>'✅ 模板已修复','✓ Active'=>'✓ 活跃','✓ Active at /lf-sitemap.xml'=>'✓ 在 /lf-sitemap.xml 处激活','✓ Active — %d URL entry with language alternates'=>'✓ 活跃 — %d 个 URL 条目具有语言备用链接' . "\0" . '','✓ Active — full OG + Twitter Cards'=>'✓ 活跃 — 完整的 OG + Twitter 卡片','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ 活跃 — 仅限区域标签（og:locale, og:locale:alternate）','✓ All parts created.'=>'✓ 所有部分已创建。','✓ All templates created.'=>'✓ 所有模板已创建。','✓ All translated.'=>'✓ 所有已翻译。','✓ All URLs submitted to IndexNow successfully.'=>'✓ 所有提交到 IndexNow 的 URL 都已成功。','✓ Configured'=>'✓ 已配置','✓ Connection OK'=>'✓ 连接正常','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ 内容已生成 — 查看覆盖层以审查、完善和应用。','✓ Done'=>'✓ 完成','✓ Enabled'=>'✓ 已启用','✓ Good length'=>'✓ 长度合适','✓ Hreflang active'=>'✓ Hreflang 激活','✓ In safe storage'=>'✓ 在安全存储中','✓ Key file is publicly reachable.'=>'✓ 密钥文件是公开可访问的。','✓ Language installed.'=>'✓ 语言已安装。','✓ LF outputs'=>'✓ LF 输出','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF 输出文章 / 网页 / 网站','✓ LF outputs full OG + Twitter Cards'=>'✓ LF 输出完整的 OG + Twitter 卡片','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF 输出 — 插件 hreflang 被抑制','✓ Links fixed.'=>'✓ 链接已修复。','✓ Nav refs fixed.'=>'✓ 导航引用已修复。','✓ Parts fixed.'=>'✓ 部分已修复。','✓ Pattern translated.'=>'✓ 模式已翻译。','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ 找到物理 robots.txt 文件。LF 的站点地图指令存在。','✓ Refined — review the updated draft above.'=>'✓ 已完善——请审查上方更新的草稿。','✓ Translation saved'=>'✓ 翻译已保存','✓ WP canonical replaced (self-referencing)'=>'✓ WP 规范标签已替换（自引用）','✗ Disabled'=>'✗ 已禁用','✗ Error:'=>'✗ 错误：','✗ Failed:'=>'✗ 失败：','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ IndexNow 提交失败。请检查密钥文件是否公开可访问（见下文）并重试。','✗ Key file is not reachable.'=>'✗ 密钥文件无法访问。','✗ Not configured'=>'✗ 未配置','✗ Too long'=>'✗ 太长','✗ Too short'=>'✗ 太短','❌ Failed'=>'❌ 失败','📄 Wrong template'=>'📄 错误的模板','📍 Stale path (page moved)'=>'📍 过时路径（页面已移动）']];
